'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var format = require( '@stdlib/string/format' );
var isArray = require( '@stdlib/assert/is-array' );
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var pkg = require( './../package.json' ).name;
var insert = require( './../lib' );


// MAIN //

bench( format( '%s::shallow_path', pkg ), function benchmark( b ) {
	var doc;
	var out;
	var i;

	doc = [ 1, 2, 3 ];

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = insert( doc, [ '1' ], i );
		if ( !isArray( out ) ) {
			b.fail( 'should return an array' );
		}
	}
	b.toc();
	if ( !isArray( out ) ) {
		b.fail( 'should return an array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::append', pkg ), function benchmark( b ) {
	var doc;
	var out;
	var i;

	doc = [ 1, 2, 3 ];

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = insert( doc, [ '-' ], i );
		if ( !isArray( out ) ) {
			b.fail( 'should return an array' );
		}
	}
	b.toc();
	if ( !isArray( out ) ) {
		b.fail( 'should return an array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::deep_path', pkg ), function benchmark( b ) {
	var doc;
	var out;
	var i;

	doc = {
		'a': {
			'b': [ 1, 2, 3 ]
		}
	};

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = insert( doc, [ 'a', 'b', '1' ], i );
		if ( !isPlainObject( out ) ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isPlainObject( out ) ) {
		b.fail( 'should return a plain object' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
